void ScriptSession::arrowStatusInfo(SpellInfo& s){
    auto field=[&](const char* key){return definitions().number(s.ability,"AbilityData",std::string(key)+std::to_string(s.level));};auto count=[](float value,unsigned maximum){if(value<0 || value>maximum || value!=std::floor(value))throw std::runtime_error("Arrow or Silence integer outside supported range");return unsigned(value);};
    if(s.kind==SpellKind::Silence){s.disableMask=count(s.amount,15);if(s.disableMask&4)throw std::runtime_error("Silence Special category is not implemented");s.missChance=s.secondary;s.moveReduction=std::max(0.f,s.loss);s.moveBonus=std::max(0.f,-s.loss);float attack=field("DataD");s.attackReduction=std::max(0.f,attack);s.attackBonus=std::max(0.f,-attack);if(!s.buff || s.duration<=0 || s.duration>86400 || s.heroDuration<0 || s.heroDuration>86400 || s.missChance<0 || s.missChance>1 || s.moveReduction>1 || s.moveBonus>10 || s.attackReduction>5 || s.attackBonus>10)throw std::runtime_error("Invalid source Silence duration or modifiers");return;}
    s.missileHoming=count(definitions().number(s.ability,"Profile","MissileHoming",1),1)!=0;if(!s.buff || s.amount>1000000 || s.speed<=0 || s.duration<0 || s.duration>86400 || s.heroDuration<0 || s.heroDuration>86400)throw std::runtime_error("Invalid source arrow damage, missile or mark duration");
    if(s.kind==SpellKind::PoisonArrows){s.attackReduction=s.loss;s.moveReduction=field("DataD");s.stackFlags=count(field("DataE"),15);if(s.amount<0 || s.secondary<0 || s.secondary>1000000 || s.attackReduction<0 || s.attackReduction>5 || s.moveReduction<0 || s.moveReduction>1)throw std::runtime_error("Invalid source Poison Arrows damage or speed factors");return;}
    if(s.kind==SpellKind::ColdArrows){s.moveReduction=s.secondary;s.attackReduction=s.loss;s.stackFlags=count(field("DataD"),15);if(s.moveReduction<0 || s.moveReduction>1 || s.attackReduction<0 || s.attackReduction>5)throw std::runtime_error("Invalid source Cold Arrows movement or attack factor");return;}
    s.passiveAttack=definitions().field(s.ability,"AbilityData","code")=="ANbs";if(s.passiveAttack)s.orderOn=s.orderOff=0;s.summonCount=count(s.secondary,64);s.summonDuration=s.loss;auto type=definitions().field(s.ability,"AbilityData","UnitID"+std::to_string(s.level));if(type.size()!=4 || !definitions().contains(ObjectData::code(type)) || s.summonDuration<0 || s.summonDuration>86400 || (s.summonCount && s.summonDuration<=0))throw std::runtime_error("Invalid source Black Arrow summon type or lifetime");s.summonType=ObjectData::code(type);auto buffs=definitions().field(s.ability,"AbilityData","BuffID"+std::to_string(s.level));if(buffs.size()>=9 && buffs[4]==',')s.guardBuff=ObjectData::code(buffs.substr(5,4));
}
bool ScriptSession::arrowTarget(unsigned owner,const UnitState& target,const SpellInfo& s){
    if(owner>=16 || target.removing || target.hidden() || target.swarmAgent || target.impaledAir() || target.cycloned() || number(target.life)<=0 || capability(target,"Aloc"))return false;auto& mask=s.allowed;auto classes=target.classifications(definitions().unitClasses(target.type));if(target.building?!mask.contains("structure"):target.airborne()?(!mask.contains("air") && !(target.grounded() && mask.contains("ground"))):!mask.contains("ground"))return false;if(mask.contains("organic") && (target.building || classes.find("mechanical")!=std::string::npos))return false;if(mask.contains("nonancient") && classes.find("ancient")!=std::string::npos)return false;if(classes.find("ward")!=std::string::npos && !mask.contains("ward"))return false;if((mask.contains("hero") || mask.contains("nonhero")) && !(target.hero?mask.contains("hero"):mask.contains("nonhero")))return false;bool hostile=enemy(owner,target.owner),enemies=mask.contains("enemy") || mask.contains("enemies"),friends=mask.contains("friend") || mask.contains("allies"),restricted=enemies || friends || mask.contains("neutral") || mask.contains("self");return !restricted || (hostile && enemies) || (!hostile && friends) || (target.owner>=12 && mask.contains("neutral"));
}
void ScriptSession::prepareArrowHit(const CombatProjectile& p,std::uint32_t target){
    if(!p.ability || !p.abilityLevel || !alive(target,NativeKind::Unit))return;auto& s=spellInfo(p.ability,p.abilityLevel);if(s.kind==SpellKind::PoisonArrows){auto u=units_.at(target);if(!arrowTarget(p.owner,*u,s))return;PassiveInfo poison;poison.ability=s.ability;poison.level=s.level;poison.kind=PassiveKind::PoisonAttack;poison.buff=s.buff;poison.amount=s.secondary;poison.secondary=s.attackReduction;poison.bonus=s.moveReduction;poison.duration=s.duration;poison.heroDuration=s.heroDuration;poison.stackFlags=s.stackFlags;poisonHit(target,p,poison);return;}if(s.kind!=SpellKind::BlackArrow)return;auto u=units_.at(target);if(u->illusion || (u->hero?s.heroDuration:s.duration)<=0 || capability(*u,"Amim") || !arrowTarget(p.owner,*u,s))return;applyBuff(target,p.source,s,BuffKind::BlackArrow);if(!alive(target,NativeKind::Unit))return;auto found=u->buffs.find(s.buff);if(found!=u->buffs.end() && found->second.kind==BuffKind::BlackArrow && found->second.source==p.source){auto& b=found->second;b.originAbility=s.ability;b.sourceLevel=s.level;b.sourceOwner=p.owner;b.applied=++spellTicket_;}
}
void ScriptSession::finishArrowHit(const CombatProjectile& p,std::uint32_t target,std::uint64_t revision){
    if(!p.ability || !p.abilityLevel || !alive(target,NativeKind::Unit))return;auto& s=spellInfo(p.ability,p.abilityLevel);if(s.kind!=SpellKind::ColdArrows)return;auto u=units_.at(target);if(u->removing || u->deathRevision!=revision || number(u->life)<=0 || (u->hero?s.heroDuration:s.duration)<=0 || capability(*u,"Amim") || !arrowTarget(p.owner,*u,s))return;applyBuff(target,p.source,s,BuffKind::ColdArrows);if(!alive(target,NativeKind::Unit))return;auto found=u->buffs.find(s.buff);if(found!=u->buffs.end() && found->second.kind==BuffKind::ColdArrows){auto& b=found->second;b.originAbility=s.ability;b.sourceLevel=s.level;b.sourceOwner=p.owner;b.stackFlags=s.stackFlags;}
}
void ScriptSession::summonedEvent(std::uint32_t source,std::uint32_t summoned,unsigned owner){
    bool exists=alive(source,NativeKind::Unit) && !units_.at(source)->removing;ScriptContext context;context.summoningUnit=context.triggerUnit=context.triggerWidget=exists?source:0;context.summonedUnit=summoned;context.triggerPlayer=handleBase+owner;auto events=unitEventSnapshot(owner,47,exists?source:0,84);for(auto id:events)fire(id,context);
}
void ScriptSession::blackArrowDeath(const UnitState& victim){
    if(victim.hero || victim.building || victim.illusion || victim.exploded || !alive(victim.handle,NativeKind::Unit) || victim.classifications(definitions().unitClasses(victim.type)).find("mechanical")!=std::string::npos)return;const UnitBuff* mark=nullptr;for(auto& [id,b]:victim.buffs)if(b.kind==BuffKind::BlackArrow && b.remaining>0 && b.originAbility && b.sourceLevel && b.sourceOwner<16 && (!mark || b.applied>mark->applied))mark=&b;if(!mark)return;auto& s=spellInfo(mark->originAbility,mark->sourceLevel);if(!s.summonCount)return;auto current=units_.at(victim.handle);auto active=[&]{return alive(victim.handle,NativeKind::Unit) && !current->removing && number(current->life)<=0 && current->deathRevision==victim.deathRevision;};WorldPoint point{victim.x,victim.y};if(!active() || (current->corpse && current->corpse->consumed) || !summonPoint(point,s.summonType))return;if(current->corpse){current->corpse->consumed=true;current->corpse->flags=0;}
    for(unsigned i=0;i<s.summonCount;++i){if(!active())return;auto at=summonPoint(point,s.summonType);if(!at)break;auto handle=createUnit(mark->sourceOwner,s.summonType,at->x,at->y,victim.facing);if(!alive(handle.bits,NativeKind::Unit))continue;auto u=units_.at(handle.bits);if(!active() || u->removing || number(u->life)<=0 || u->owner!=mark->sourceOwner || u->type!=s.summonType){if(!u->removing)removeUnit(handle.bits);if(!active())return;continue;}u->summoner=mark->source;u->summonAbility=s.ability;auto buff=s.guardBuff?s.guardBuff:s.buff;u->timedLife=TimedLife{buff,s.summonDuration,s.summonDuration,false};if(buff)u->abilities[buff]=1;spellVisual(s,"TargetArt",handle.bits,*at);summonedEvent(mark->source,handle.bits,mark->sourceOwner);}
}
void ScriptSession::silenceEffect(std::uint32_t source,const SpellInfo& s,WorldPoint point,unsigned owner){
    auto kind=s.kind==SpellKind::DrunkenHaze?BuffKind::DrunkenHaze:BuffKind::Silence;auto targets=spellTargets(source,s,point,owner);spellVisual(s,"EffectArt",0,point);for(auto id:targets){if(!alive(source,NativeKind::Unit))break;if(!alive(id,NativeKind::Unit) || !spellTarget(*units_.at(source),*units_.at(id),s,false,owner))continue;auto u=units_.at(id);applyBuff(id,source,s,kind);if(!alive(id,NativeKind::Unit) || u->removing || number(u->life)<=0)continue;auto found=u->buffs.find(s.buff);if(found==u->buffs.end() || found->second.kind!=kind)continue;if(u->silenced() && u->cast && !u->cast->item)cancelCast(*u);if(!alive(id,NativeKind::Unit) || u->removing)continue;if(u->combat.windup){auto w=unitWeapon(*u,u->combat.windup->weapon);if(u->attackPrevented(w.kind!="normal")){u->combat.windup.reset();++u->combat.revision;}}}
}
bool ScriptSession::useSilenceItem(std::uint32_t id,std::uint32_t itemId,WorldPoint point){
    if(!alive(id,NativeKind::Unit) || !alive(itemId,NativeKind::Item))return false;auto u=units_.at(id);auto item=items_.at(itemId);auto abilities=itemActiveAbilities(item->type);if(abilities.size()!=1)return false;auto& s=spellInfo(abilities.front(),1);if(s.kind!=SpellKind::Silence || !itemSpellReady(*u,s,itemId))return false;if(!std::isfinite(number(point.x)) || !std::isfinite(number(point.y)))throw std::runtime_error("Invalid Silence item point");auto slot=std::find(u->inventory.begin(),u->inventory.end(),itemId);if(slot==u->inventory.end())return false;return beginSpell(id,s.ability,0,point,SpellTargeting::Point,false,852008u+unsigned(slot-u->inventory.begin()),itemId);
}
